import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("SBIN.NS");
  const [loading, setLoading] = useState(false);

  const stockList = [
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "Tata Motors", symbol: "TATAMOTORS.NS" },
    { name: "Zomato", symbol: "ZOMATO.NS" },
    { name: "Paytm", symbol: "PAYTM.NS" },
    { name: "Reliance", symbol: "RELIANCE.NS" },
    { name: "Adani Ent", symbol: "ADANIENT.NS" }
  ];

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        console.log("API Response:", res.data); // Debugging-ku
        setData(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error("Backend connection failed!", err);
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData(selectedStock);
  }, [selectedStock]);

  // Data varadhukku munnadi oru simple loading state
  if (!data && !loading) return <div style={{color: 'white', textAlign: 'center', marginTop: '50px'}}>Connecting to QuantShield Engine...</div>;

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#c9d1d9', minHeight: '100vh', padding: '20px', fontFamily: 'monospace' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '1px solid #30363d', paddingBottom: '10px', marginBottom: '20px' }}>
        <h2 style={{ color: '#58a6ff', margin: 0 }}>🛡️ QuantShield AI Dashboard</h2>
        <button onClick={() => fetchData(selectedStock)} style={{ background: '#238636', color: 'white', border: 'none', padding: '8px 15px', borderRadius: '5px', cursor: 'pointer' }}>
            {loading ? 'ANALYZING...' : '🔄 REFRESH LIVE'}
        </button>
      </div>

      <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d', marginBottom: '20px' }}>
        <label style={{ marginRight: '15px', fontWeight: 'bold' }}>📂 PORTFOLIO ASSET:</label>
        <select 
          value={selectedStock} 
          onChange={(e) => setSelectedStock(e.target.value)}
          style={{ background: '#0d1117', color: 'white', border: '1px solid #58a6ff', padding: '10px', borderRadius: '5px', width: '300px' }}
        >
          {stockList.map(s => <option key={s.symbol} value={s.symbol}>{s.name} ({s.symbol})</option>)}
        </select>
      </div>

      {data && (
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px' }}>
          
          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <h3 style={{ color: '#ff4b4b' }}>📊 Risk Analysis</h3>
            
            <div style={{ background: '#0d1117', padding: '20px', borderRadius: '10px', border: '1px solid #58a6ff', marginBottom: '20px', textAlign: 'center' }}>
              <span style={{ color: '#8b949e', fontSize: '12px' }}>CURRENT MARKET PRICE</span>
              <h1 style={{ color: '#58a6ff', margin: '5px 0' }}>₹{data.current_price || '---'}</h1>
            </div>

            <div style={{ lineHeight: '3', fontSize: '18px' }}>
              <div>Volatility Index: <b style={{float: 'right', color: '#f85149'}}>{data.volatility || 'N/A'}</b></div>
              <div>Market Regime: <b style={{float: 'right'}}>{data.regime || 'N/A'}</b></div>
              <div>Momentum (BSI): <b style={{float: 'right', color: '#d2a8ff'}}>{data.bsi_score || 'N/A'}</b></div>
            </div>

            <div style={{ 
              marginTop: '40px', padding: '15px', textAlign: 'center', borderRadius: '8px',
              background: data.regime === "STRESS" ? '#4a151b' : '#064e3b',
              border: `2px solid ${data.regime === "STRESS" ? '#f85149' : '#238636'}`
            }}>
              🛡️ GHOST HEDGE: {data.regime === "STRESS" ? "ACTIVE" : "INACTIVE"}
            </div>
          </div>

          <div style={{ background: '#161b22', padding: '20px', borderRadius: '8px', border: '1px solid #30363d' }}>
            <div style={{ background: '#0d1117', padding: '15px', borderRadius: '10px', border: '1px solid #30363d', marginBottom: '20px' }}>
              <h4 style={{ color: '#f1e05a', marginTop: 0 }}>🔮 2-DAY AI FORECAST</h4>
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <p>Day 1: <b>₹{data.prediction?.day1 || '---'}</b></p>
                <p>Day 2: <b>₹{data.prediction?.day2 || '---'}</b></p>
                <b style={{ color: data.prediction?.trend === "UP" ? '#3fb950' : '#f85149' }}>{data.prediction?.trend} ({data.prediction?.pct})</b>
              </div>
            </div>

            <h3 style={{ color: '#58a6ff' }}>🎲 Portfolio Simulation (₹10,000)</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px' }}>
              <div style={{ background: '#0d1117', padding: '15px', borderLeft: '5px solid #238636' }}>
                <span>Expected Value</span>
                <h2 style={{ color: '#3fb950' }}>₹{data.forecast?.expected || '0'}</h2>
              </div>
              <div style={{ background: '#0d1117', padding: '15px', borderLeft: '5px solid #f85149' }}>
                <span>Worst Case</span>
                <h2 style={{ color: '#f85149' }}>₹{data.forecast?.worst_case || '0'}</h2>
              </div>
            </div>

            <div style={{ 
              marginTop: '30px', padding: '20px', textAlign: 'center', borderRadius: '10px', 
              background: data.decision === "BUY" ? '#238636' : data.decision === "AVOID" ? '#f85149' : '#f1e05a',
              color: 'white', fontSize: '24px', fontWeight: 'bold'
            }}>
              🤖 AI VERDICT: {data.decision || 'HOLD'}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
